<?php
$dbHost=getenv("DB_HOST")?:"localhost";$dbUser=getenv("DB_USER")?:"root";$dbPass=getenv("DB_PASS")?:"";$dbName=getenv("DB_NAME")?:"sales_recruitment";
$c=new mysqli($dbHost,$dbUser,$dbPass);if($c->connect_error)die("Database connection failed.");$c->query("CREATE DATABASE IF NOT EXISTS `$dbName` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");$c->select_db($dbName);
$c->query("CREATE TABLE IF NOT EXISTS applications(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),email VARCHAR(150),phone VARCHAR(20),position VARCHAR(100),experience INT,resume_link VARCHAR(255),status VARCHAR(30) DEFAULT 'New',applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
$msg="";
if($_SERVER["REQUEST_METHOD"]==="POST"){ $n=trim($_POST["name"]??"");$e=trim($_POST["email"]??"");$p=trim($_POST["phone"]??"");$pos=trim($_POST["position"]??"");$x=(int)($_POST["experience"]??0);$r=trim($_POST["resume_link"]??"");if($n&&filter_var($e,FILTER_VALIDATE_EMAIL)&&$pos){$s=$c->prepare("INSERT INTO applications(name,email,phone,position,experience,resume_link) VALUES(?,?,?,?,?,?)");$s->bind_param("ssssis",$n,$e,$p,$pos,$x,$r);$s->execute();$s->close();$msg="Application submitted successfully.";}}
$rows=$c->query("SELECT * FROM applications ORDER BY id DESC LIMIT 100");
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,"UTF-8");}
?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sales Recruitment</title><style>body{font-family:Arial;background:#f5f7fb;margin:0}.head{background:#7c3aed;color:white;padding:25px 7%;font-size:25px;font-weight:bold}.wrap{max-width:1100px;margin:35px auto;padding:20px}.card{background:#fff;padding:28px;border-radius:15px;box-shadow:0 5px 25px #0001;margin-bottom:25px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}label{font-weight:bold}input,select{width:100%;padding:12px;margin-top:7px;border:1px solid #ccc;border-radius:7px;box-sizing:border-box}button{padding:13px 20px;background:#7c3aed;color:white;border:0;border-radius:7px;font-weight:bold;margin-top:18px}table{width:100%;border-collapse:collapse;min-width:900px}th,td{padding:11px;border-bottom:1px solid #ddd;text-align:left}th{background:#7c3aed;color:#fff}.table{overflow:auto}.msg{padding:12px;background:#dcfce7;color:#166534;border-radius:7px}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><div class="head">💼 Sales Job Recruitment System</div><div class="wrap"><div class="card"><h2>Apply for Sales Position</h2><?php if($msg):?><div class="msg"><?=e($msg)?></div><?php endif;?><form method="post"><div class="grid"><div><label>Name</label><input name="name" required></div><div><label>Email</label><input type="email" name="email" required></div><div><label>Phone</label><input name="phone"></div><div><label>Position</label><select name="position" required><option value="">Select</option><option>Sales Executive</option><option>Sales Manager</option><option>Business Development Executive</option><option>Area Sales Manager</option></select></div><div><label>Experience (years)</label><input type="number" name="experience" min="0" max="50"></div><div><label>Resume Link</label><input name="resume_link" placeholder="https://..."></div></div><button>Submit Application</button></form></div><div class="card"><h2>Recruitment Records</h2><div class="table"><table><tr><th>ID</th><th>Name</th><th>Email</th><th>Position</th><th>Experience</th><th>Status</th><th>Date</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r["id"])?></td><td><?=e($r["name"])?></td><td><?=e($r["email"])?></td><td><?=e($r["position"])?></td><td><?=e($r["experience"])?></td><td><?=e($r["status"])?></td><td><?=e($r["applied_at"])?></td></tr><?php endwhile;?></table></div></div></div></body></html><?php $c->close();?>